import{_ as a,o,c as t,a5 as r}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 63 话 设计令牌的分层与落地","description":"","frontmatter":{},"headers":[],"relativePath":"comics/architecture/EP.63-design-tokens.md","filePath":"comics/architecture/EP.63-design-tokens.md","lastUpdated":1793853676000}'),i={name:"comics/architecture/EP.63-design-tokens.md"};function l(c,e,n,d,s,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-63-话-设计令牌的分层与落地" tabindex="-1">漫画 · 第 63 话 设计令牌的分层与落地 <a class="header-anchor" href="#漫画-·-第-63-话-设计令牌的分层与落地" aria-label="Permalink to &quot;漫画 · 第 63 话 设计令牌的分层与落地&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/architecture/01-design-tokens">docs/architecture/01-design-tokens.md</a> ｜ 原画：<a href="./EP.63-design-tokens.svg">EP.63-design-tokens.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她把 Figma 色板全量导成变量，以为「变量化」就是设计系统。</li><li><strong>标签君</strong>：结构师。他坚持令牌要分三层，否则换肤时必然漏改。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱把品牌色板导成 <code>--blue-600</code>、<code>--gray-100</code> 等变量，组件里直接引用。上线暗色主题后，三成组件仍然是浅色，因为组件引用的是原始值，不是「角色」。标签君帮她把令牌拆成原始、语义、组件三层，主题只重绑语义层，引用链自动传导。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>「把颜色写成变量」只解决了复用，没有解决治理。原始层只回答「这个值是多少」，不回答「这个值扮演什么角色」。组件直接引用 <code>--blue-600</code>，换肤时就没有任何一层可以统一改写它。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三层各司其职：Primitive 存实际值，Semantic 表达角色（<code>--color-action</code>），Component 暴露组件接口（<code>--button-bg</code>）。自定义属性是运行时解析的，<code>var()</code> 在计算值时展开，所以语义层被主题重绑后，组件层的引用会自动拿到新值。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>像素酱保留原始色板，新增几十个语义令牌，组件只消费语义与组件令牌；主题覆盖只改语义层；用 lint 禁止组件直引 <code>--{color}-{number}</code>。结果是暗色覆盖率从 70% 升到 100%，新增品牌主题只需二十行语义映射。</p><p>配套示例可现场验证：拖动原始色板，观察语义层与组件层逐层传导；切换到「组件直引原始值」的模式，换肤立刻失效。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>三层令牌：原始存值、语义定角色、组件暴露接口，缺一层就会漏改。</li><li>组件直引原始值是换肤失效的头号原因，需用 lint 拦截。</li><li>语义令牌按角色命名（<code>--color-danger</code>），不按颜色命名（<code>--color-red</code>）。</li><li>令牌不是越多越好：语义层控制在几十个，组件层按组件收敛。</li><li>新增语义令牌时，所有主题都要补齐，否则回退到旧值。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把 Figma 的 120 个色板全部导出为 <code>--color-*</code> 变量，是否就算建立了设计令牌？</p><p><strong>答</strong>：不算。这只是原始层，缺少语义与组件两层。真正的令牌体系要回答「这个颜色在这里扮演什么角色」。没有语义层，主题切换就没有统一改写点；没有组件层，组件之间的覆盖会互相污染。分层的目的不是增加变量，而是把「值」与「角色」隔离。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>在示例中切换「三层模式 / 直引原始值模式」，对比换肤结果：<a href="./../../examples/architecture/01-design-tokens">examples/architecture/01-design-tokens</a></li><li>修改 <code>--blue-600</code>，观察哪些组件跟随、哪些没有，解释差异。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 64 话《cascade layers 与 @scope 的工程用法》——优先级不该靠堆特异性，边界也不该靠长选择器。</p>',23)])])}const m=a(i,[["render",l]]);export{p as __pageData,m as default};
